  --text: #e9f1f7;
  --text-muted: #b7c5d3;
  --accent: #00b4d8;
  --accent-2: #0077b6;
  --success: #6cc24a;
  --border: #2a3f55;
  --danger: #ff6b6b;
  --shadow: 0 12px 28px rgba(0, 0, 0, 0.35);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: linear-gradient(180deg, var(--bg-900) 0%, #0a1624 100%);
  color: var(--text);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
img, svg { max-width: 100%; }

.container {
  width: min(1150px, 92vw);
  margin: 0 auto;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.92);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.nav {
  min-height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  letter-spacing: 0.2px;
}
.brand-mark {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  display: grid;
  place-items: center;
  color: #032033;
  font-weight: 800;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 18px;
}
.nav-link {
  color: var(--text-muted);
  font-weight: 500;
}
.nav-link:hover, .nav-link[aria-current="page"] { color: var(--text); }

.dropdown {
  position: relative;
}
.dropdown-toggle {
  border: 0;
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  cursor: pointer;
}
.dropdown-menu {
  display: none;
  position: absolute;
  top: calc(100% + 10px);
  left: 0;
  min-width: 220px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: var(--shadow);
  overflow: hidden;
}
.dropdown.open .dropdown-menu { display: block; }
.dropdown-menu a {
  display: block;
  padding: 12px 14px;
  color: var(--text-muted);
}
.dropdown-menu a:hover { background: #233a54; color: var(--text); }

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 16px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #042238;
}
.btn-primary:hover { filter: brightness(1.08); }
.btn-secondary {
  border-color: var(--border);
  color: var(--text);
  background: transparent;
}

.hero { padding: 84px 0 54px; }
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 36px;
  align-items: center;
}
.hero h1 {
  font-size: clamp(2rem, 3.8vw, 3.4rem);
  line-height: 1.15;
  margin: 0 0 16px;
}
.hero p { color: var(--text-muted); margin: 0 0 26px; max-width: 62ch; }
.cta-row { display: flex; gap: 12px; flex-wrap: wrap; }

.card {
  background: linear-gradient(180deg, var(--surface), var(--surface-2));
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px;
}

.section { padding: 56px 0; }
.section h2 { margin: 0 0 12px; font-size: clamp(1.5rem, 2.6vw, 2.2rem); }
.section-intro { color: var(--text-muted); margin: 0 0 24px; }

.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }

.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}
.tab-btn {
  background: #11263b;
  color: var(--text-muted);
  border: 1px solid var(--border);
  padding: 10px 14px;
  border-radius: 999px;
  cursor: pointer;
  font-weight: 600;
}
.tab-btn.active {
  color: #06283a;
  background: linear-gradient(135deg, #67dcf2, var(--accent));
}
.tab-panel { display: none; }
.tab-panel.active { display: block; }

.use-case-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.use-case-item h3 { margin-top: 0; margin-bottom: 8px; font-size: 1.04rem; }
.use-case-item p { margin: 0; color: var(--text-muted); }

.accordion-item { border: 1px solid var(--border); border-radius: 12px; overflow: hidden; margin-bottom: 10px; }
.accordion-header {
  width: 100%; text-align: left; border: 0; background: #12263a; color: var(--text);
  padding: 14px 16px; font-weight: 700; cursor: pointer;
}
.accordion-panel { display: none; padding: 14px 16px; background: #162a40; color: var(--text-muted); }
.accordion-item.active .accordion-panel { display: block; }

.circle-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.circle {
  border-radius: 50%;
  width: 180px;
  height: 180px;
  margin: 0 auto;
  display: grid;
  place-content: center;
  text-align: center;
  border: 10px solid #2a4b68;
  background: radial-gradient(circle at 30% 20%, #244866, #14263b 70%);
}
.circle strong { font-size: 1.9rem; display: block; }
.circle span { color: var(--text-muted); font-size: 0.9rem; }

.timeline-item { margin-bottom: 14px; }
.progress {
  background: #0f1f31;
  border: 1px solid var(--border);
  border-radius: 999px;
  height: 12px;
  overflow: hidden;
}
.progress > div {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--success));
}

.carousel-track {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}
.testimonial { min-height: 180px; }
.carousel-dots { display: flex; justify-content: center; gap: 8px; margin-top: 14px; }
.dot {
  width: 10px; height: 10px; border-radius: 50%; border: 0; cursor: pointer;
  background: #31506d;
}
.dot.active { background: var(--accent); }

.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }
label { display: block; font-size: 0.92rem; margin-bottom: 6px; }
input, select, textarea {
  width: 100%;
  padding: 11px 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: #0f1f31;
  color: var(--text);
}
textarea { min-height: 130px; resize: vertical; }
.error { color: var(--danger); font-size: 0.85rem; margin-top: 6px; }
.success-msg {
  margin-top: 10px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid #2f7f5f;
  color: #aff5d8;
  background: rgba(18, 93, 65, 0.2);
}

.cookie-banner {
  position: fixed;
  left: 16px;
  right: 16px;
  bottom: 16px;
  z-index: 1200;
  display: none;
}
.cookie-banner .card {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.diagram {
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 14px;
  background: linear-gradient(180deg, #102338, #0e1e30);
}
